'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const core=require('../lib/core.cjs'),v4=require('../lib/legacy-v4.cjs');
const AT='2026-11-23T02:00:00.000Z',owner={kind:'owner'},host={kind:'host'},agent=id=>({kind:'session',id}),results=[];
function test(name,run){try{run();results.push({name,passed:true});}catch(e){results.push({name,passed:false,error:e.stack});console.error(name,e);}}
function direct(s,who,c){const before=JSON.stringify(s);try{return core.transition(s,who,{...(who.kind==='owner'?{expectedRevision:s.revision}:{}),...c},AT);}finally{assert.equal(JSON.stringify(s),before);}}
let dispatchSequence=0;
function raw(s,who,c){
 if(who.kind==='session'&&c.type==='update-work'&&c.assignments?.length){
  const n=++dispatchSequence,dispatchId='test-dispatch-'+n,teamId=c.teamId;
  s=direct(s,host,{type:'user-input',sessionId:who.id,userMessageId:'discussion-'+n}).state;
  const {type,teamId:_,expectedPlanVersion,acknowledge,...plan}=c;
  s=direct(s,who,{type:'prepare-dispatch',teamId,dispatchId,expectedPlanVersion,expectedUserMessageId:'discussion-'+n,summary:'Test-only exact plan preview',permissionExpectations:'Native permissions remain unchanged',plan}).state;
  s=direct(s,host,{type:'user-input',sessionId:who.id,userMessageId:'actual-user-confirm-'+n}).state;
  return direct(s,who,{type:'confirm-dispatch',teamId,dispatchId,expectedUserMessageId:'actual-user-confirm-'+n,approved:true});
 }
 return direct(s,who,c);
}
const go=(s,who,c)=>raw(s,who,c).state;
function bad(s,who,c,code){assert.throws(()=>{if(code==='INVALID_DEPENDENCY'&&c.type==='update-work'){let q=direct(s,host,{type:'user-input',sessionId:who.id,userMessageId:'negative-preview'}).state;const {type,teamId,expectedPlanVersion,...plan}=c;return direct(q,who,{type:'prepare-dispatch',teamId,dispatchId:'negative',expectedPlanVersion,expectedUserMessageId:'negative-preview',summary:'Reject invalid topology',permissionExpectations:'None',plan});}return go(s,who,c);},e=>{assert.equal(e.code,code);return true;});}
function setup(){return go(core.initialState(),owner,{type:'save-team',teamId:'t',title:'Delivery',description:'',managerId:'m',memberIds:['w','x']});}
const plan=s=>s.teams[0].planVersion,current=(s,id='w')=>s.teams[0].assignments.find(a=>a.targetId===id&&a.status==='current'),guard=a=>({assignmentRevision:a.revision,assignmentVersion:a.version});
const batch=(s,c)=>go(s,agent('m'),{type:'update-work',teamId:'t',expectedPlanVersion:plan(s),...c});
const assign=(s,id='w')=>batch(s,{assignments:[{targetId:id,text:'Deliver outcome',expectedAssignment:current(s,id)?guard(current(s,id)):null}]});
const finish=(s,id='w',reportId='r')=>raw(s,agent(id),{type:'finish-assignment',teamId:'t',...guard(current(s,id)),reportId,text:'Completed with evidence'});
function message(s,who,c){return go(s,agent(who),{type:'message',teamId:'t',...c});}
test('manager can confirm identity revision1 and explicitly agree atomically; workers cannot forge it',()=>{
 let s=setup();const c={type:'propose-identity',teamId:'t',proposalId:'p',targetId:'w',identity:'Creator',text:'Stable creator role',concernedIds:['m','w'],ownResponse:'agree'};
 bad(s,agent('w'),c,'FORBIDDEN');let out=raw(s,agent('m'),c);s=out.state;assert.equal(out.result.proposal.readiness,'awaiting-responses');assert.deepEqual(out.result.proposal.missingResponses,['w']);assert.equal(out.result.proposal.responses[0].sessionId,'m');assert.equal(s.proposals[0].revisions.length,1);
 assert(core.pendingWakes(s).some(w=>w.sessionId==='w'&&w.reason==='proposal'));s=go(s,agent('w'),{type:'respond-proposal',teamId:'t',proposalId:'p',proposalRevision:1,response:'agree'});assert.equal(core.read(s,agent('m'),{type:'updates'}).proposals[0].readiness,'ready');
 assert(core.pendingWakes(s).some(w=>w.sessionId==='m'&&w.refs.proposalAction==='decide'));s=go(s,agent('m'),{type:'accept-proposal',teamId:'t',proposalId:'p',proposalRevision:1});assert.equal(s.teams[0].identities[0].text,'Creator');assert.equal(core.pendingWakes(s).some(w=>w.reason==='proposal'),false);
});
test('focus is native-session-wide, exact own release, persistent and body-free context',()=>{
 let s=assign(setup());assert.equal(core.pendingWakes(s,'w').length,1);s=go(s,host,{type:'user-input',sessionId:'w',userMessageId:'human-1'});assert.equal(core.pendingWakes(s,'w').length,0);assert.equal(s.wakeups[0].status,'pending');
 s=message(s,'x',{messageId:'info',to:'w',kind:'information',text:'DO NOT INJECT BODY'});assert.doesNotMatch(core.context(s,'w'),/DO NOT INJECT BODY/);assert.match(core.context(s,'w'),/human-1/);
 bad(s,agent('x'),{type:'set-user-focus',withUser:false,expectedUserMessageId:'human-1'},'STALE_FOCUS');bad(s,agent('w'),{type:'set-user-focus',withUser:false,expectedUserMessageId:'old'},'STALE_FOCUS');
 s=go(s,host,{type:'user-input',sessionId:'w',userMessageId:'human-2'});bad(s,agent('w'),{type:'set-user-focus',withUser:false,expectedUserMessageId:'human-1'},'STALE_FOCUS');s=go(s,agent('w'),{type:'set-user-focus',withUser:false,expectedUserMessageId:'human-2'});assert.equal(core.pendingWakes(s,'w').length,1);
 s=go(s,host,{type:'user-input',sessionId:'w',userMessageId:'human-3'});s=core.start(s,AT);assert.equal(s.sessions.find(p=>p.id==='w').focus.withUser,true);assert.equal(core.pendingWakes(s).length,0);assert(s.wakeups.every(w=>w.status==='cancelled'));
});
test('optional information/proposals never block work; exact required requests do and multiple replies release last blocker',()=>{
 let s=assign(assign(setup()),'x');s=message(s,'w',{messageId:'optional',to:'x',kind:'request',text:'Nice to know'});assert.equal(current(s).workStatus,'ready');
 s=message(s,'w',{messageId:'q1',to:'x',kind:'request',text:'Need path',blockingAssignment:guard(current(s))});s=message(s,'w',{messageId:'q2',to:'m',kind:'request',text:'Need decision',blockingAssignment:guard(current(s))});assert.equal(current(s).workStatus,'waiting');assert.deepEqual(current(s).waitingOn,['q1','q2']);
 s=message(s,'x',{messageId:'a1',to:'w',kind:'reply',replyTo:'q1',text:'Path supplied'});assert.equal(current(s).workStatus,'waiting');assert.equal(core.pendingWakes(s,'w').length,1);assert.equal(core.wakeMode(s,core.pendingWakes(s,'w')[0]),'reassess');assert.equal(current(s).waitingReason,'Awaiting required information: q2');s=message(s,'m',{messageId:'a2',to:'w',kind:'reply',replyTo:'q2',text:'Decision supplied'});assert.equal(current(s).workStatus,'ready');assert.deepEqual(current(s).waitingOn,[]);assert(core.pendingWakes(s,'w').some(w=>w.reason==='reply'));
 bad(s,agent('x'),{type:'message',teamId:'t',messageId:'again',to:'w',kind:'reply',replyTo:'q1',text:'repeat'},'STALE_REQUEST');
});
test('replacement closes old request; a late reply cannot release new work and information is durable before wake',()=>{
 let s=assign(setup());s=message(s,'w',{messageId:'q',to:'x',kind:'request',text:'Required',blockingAssignment:guard(current(s))});s=assign(s);assert.equal(s.messages[0].closedReason,'replaced');bad(s,agent('x'),{type:'message',teamId:'t',messageId:'a',to:'w',kind:'reply',replyTo:'q',text:'Late'},'STALE_REQUEST');
 const box=core.read(s,agent('m'),{type:'updates'});assert(!box.messages.some(m=>m.id==='q'));assert.equal(core.read(s,owner,{type:'history',teamId:'t'}).messages[0].id,'q');
});
test('predecessor binding supports direct A to B handoff without manager relay or intermediate wake',()=>{
 let s=batch(setup(),{assignments:[{targetId:'w',text:'Create safe file',expectedAssignment:null},{targetId:'x',text:'Edit after creator',expectedAssignment:null,afterSessionId:'w'}]});assert.equal(current(s,'x').workStatus,'waiting');assert.equal(current(s,'x').after.assignmentRevision,current(s).revision);
 s=finish(s).state;assert.equal(current(s,'x').workStatus,'ready');assert.equal(s.messages[0].kind,'handoff');assert.equal(core.pendingWakes(s,'m').length,0);assert(core.pendingWakes(s,'x').some(w=>w.reason==='handoff'));s=finish(s,'x','rx').state;assert(core.pendingWakes(s,'m').some(w=>w.reason==='completion'));
});
test('arbitrary manual waiting is not released by peer handoff; predecessor replacement never retargets old binding',()=>{
 let s=batch(setup(),{assignments:[{targetId:'w',text:'Create',expectedAssignment:null},{targetId:'x',text:'Await my explicit manager release',expectedAssignment:null,workStatus:'waiting',waitingReason:'Manager release'}]});s=message(s,'w',{messageId:'h',to:'x',kind:'handoff',assignmentRevision:current(s,'x').revision,text:'Information available'});assert.equal(current(s,'x').workStatus,'waiting');assert.equal(core.pendingWakes(s,'x').length,0);
 s=batch(setup(),{assignments:[{targetId:'w',text:'Original create',expectedAssignment:null},{targetId:'x',text:'Bound edit',expectedAssignment:null,afterSessionId:'w'}]});const original=current(s).revision;s=assign(s);s=finish(s).state;assert.equal(current(s,'x').after.assignmentRevision,original);assert.equal(current(s,'x').workStatus,'waiting');
});
test('alerts have exact versions, explicit needs-user state and no fake approval',()=>{
 let s=assign(setup());s=go(s,agent('w'),{type:'raise-alert',teamId:'t',alertId:'blocked',text:'Need owner choice',needsUser:true});const profile=core.read(s,agent('m'),{type:'profile'});assert.equal(profile.alerts.length,1);assert(core.pendingWakes(s,'m').some(w=>w.reason==='alert'));
 const native={observation:{availability:'available',execution:'running',archived:false},focus:{withUser:true}};assert.equal(core.visibleState(native,current(s),profile.alerts),'Needs intervention');assert.equal(core.visibleState(native,current(s),[]),'With user');assert.equal(core.visibleState({...native.observation,approvalPending:true},current(s),[]),'Approval needed');
 bad(s,agent('w'),{type:'resolve-alert',teamId:'t',alertId:'blocked',expectedAlertVersion:2},'STALE_ALERT');s=go(s,agent('w'),{type:'resolve-alert',teamId:'t',alertId:'blocked',expectedAlertVersion:1});assert.equal(s.alerts[0].version,2);assert.equal(core.pendingWakes(s,'m').length,0);
});
test('wake claim settle defer preserves record-first exact attempt and at-most-once failed outcome',()=>{
 let s=assign(setup()),ids=core.pendingWakes(s).map(w=>w.id);s=go(s,host,{type:'claim-wakes',wakeIds:ids,messageId:'native-attempt'});assert.equal(core.pendingWakes(s).length,0);s=go(s,host,{type:'user-input',sessionId:'w',userMessageId:'human'});s=go(s,host,{type:'defer-wakes',wakeIds:ids,messageId:'native-attempt'});assert.equal(s.wakeups[0].status,'pending');s=go(s,host,{type:'settle-wakes',wakeIds:ids,status:'sent',messageId:'native-attempt'});assert.equal(s.wakeups[0].status,'pending');
 s=go(s,agent('w'),{type:'set-user-focus',withUser:false,expectedUserMessageId:'human'});s=go(s,host,{type:'claim-wakes',wakeIds:ids,messageId:'native-attempt-2'});s=go(s,host,{type:'settle-wakes',wakeIds:ids,status:'failed',messageId:'native-attempt-2',error:'Uncertain append'});assert.equal(s.wakeups[0].status,'failed');assert.equal(core.pendingWakes(s).length,0);assert.equal(s.alerts[0].needsUser,true);assert.equal(s.wakeups.length,1);
});
