function prepared(s=setup(),planValue={assignments:[{targetId:'w',text:'Exact approved task',expectedAssignment:null}]}){s=direct(s,host,{type:'user-input',sessionId:'m',userMessageId:'discussion'}).state;return direct(s,agent('m'),{type:'prepare-dispatch',teamId:'t',dispatchId:'dispatch',expectedPlanVersion:plan(s),expectedUserMessageId:'discussion',summary:'Exact outcome and scope',permissionExpectations:'Worker must request any native permission',plan:planValue}).state;}
