function unanimous(s,who='w',id='p'){s=go(s,agent(who),{type:'report',teamId:'t',reportId:'origin-'+id,text:'Discuss current task',status:'progress'});s=go(s,agent(who),{type:'propose',teamId:'t',proposalId:id,reportId:'origin-'+id,reportVersion:1,text:'Use peer decision without changing assigned task',suggestedConcernedIds:[who]});s=go(s,agent('m'),{type:'revise-proposal',teamId:'t',proposalId:id,proposalRevision:1,text:'Exact current decision',concernedIds:[],ownResponse:'agree'});return go(s,agent(who),{type:'respond-proposal',teamId:'t',proposalId:id,proposalRevision:2,response:'agree'});}
